if (points.empty()) {
    return BoundingBox2{Point2d{0, 0}, Point2d{0, 0}};
}
std::vector<Point2d> hull = points;
std::sort(hull.begin(), hull.end(), [](const Point2d& a, const Point2d& b) {
    return a.x < b.x || (a.x == b.x && a.y < b.y);
});
std::vector<Point2d> lower;
for (const auto& p : hull) {
    while (lower.size() >= 2 && (lower.back().x - lower[lower.size()-2].x) * (p.y - lower[lower.size()-2].y) <= (lower.back().y - lower[lower.size()-2].y) * (p.x - lower[lower.size()-2].x)) {
        lower.pop_back();
    }
    lower.push_back(p);
}
std::vector<Point2d> upper;
for (int i = static_cast<int>(hull.size()) - 1; i >= 0; --i) {
    while (upper.size() >= 2 && (upper.back().x - upper[upper.size()-2].x) * (hull[i].y - upper[upper.size()-2].y) <= (upper.back().y - upper[upper.size()-2].y) * (hull[i].x - upper[upper.size()-2].x)) {
        upper.pop_back();
    }
    upper.push_back(hull[i]);
}
lower.pop_back();
upper.pop_back();
hull.clear();
hull.insert(hull.end(), lower.begin(), lower.end());
hull.insert(hull.end(), upper.begin(), upper.end());
if (hull.size() < 3) {
    Point2d minP = points[0], maxP = points[0];
    for (const auto& p : points) {
        minP.x = std::min(minP.x, p.x);
        minP.y = std::min(minP.y, p.y);
        maxP.x = std::max(maxP.x, p.x);
        maxP.y = std::max(maxP.y, p.y);
    }
    return BoundingBox2{minP, maxP};
}
double minArea = std::numeric_limits<double>::max();
BoundingBox2 result;
for (size_t i = 0; i < hull.size(); ++i) {
    size_t j = (i + 1) % hull.size();
    double dx = hull[j].x - hull[i].x;
    double dy = hull[j].y - hull[i].y;
    double length = std::sqrt(dx * dx + dy * dy);
    double ux = dx / length;
    double uy = dy / length;
    double vx = -uy;
    double vy = ux;
    double minProj = std::numeric_limits<double>::max();
    double maxProj = std::numeric_limits<double>::lowest();
    double minProjPerp = std::numeric_limits<double>::max();
    double maxProjPerp = std::numeric_limits<double>::lowest();
    for (const auto& p : points) {
        double proj = ux * (p.x - hull[i].x) + uy * (p.y - hull[i].y);
        double projPerp = vx * (p.x - hull[i].x) + vy * (p.y - hull[i].y);
        minProj = std::min(minProj, proj);
        maxProj = std::max(maxProj, proj);
        minProjPerp = std::min(minProjPerp, projPerp);
        maxProjPerp = std::max(maxProjPerp, projPerp);
    }
    double area = (maxProj - minProj) * (maxProjPerp - minProjPerp);
    if (area < minArea) {
        minArea = area;
        Point2d p1 = Point2d{hull[i].x + minProj * ux, hull[i].y + minProj * uy};
        Point2d p2 = Point2d{hull[i].x + maxProj * ux, hull[i].y + maxProj * uy};
        Point2d p3 = Point2d{hull[i].x + maxProj * ux + minProjPerp * vx, hull[i].y + maxProj * uy + minProjPerp * vy};
        Point2d p4 = Point2d{hull[i].x + minProj * ux + minProjPerp * vx, hull[i].y + minProj * uy + minProjPerp * vy};
        Point2d minCorner{std::min({p1.x, p2.x, p3.x, p4.x}), std::min({p1.y, p2.y, p3.y, p4.y})};
        Point2d maxCorner{std::max({p1.x, p2.x, p3.x, p4.x}), std::max({p1.y, p2.y, p3.y, p4.y})};
        result = BoundingBox2{minCorner, maxCorner};
    }
}
return result;

